  "summary": "The code contains critical security vulnerabilities including SQL injection and OS command injection, alongside poor resource management. The refactored code implements parameterized queries, safe subprocess execution, path sanitization, and proper context management for database connections.",
  "fixed_code": "import sqlite3\nimport subprocess\nimport os\nfrom flask import Flask, jsonify, request, Response\n\napp = Flask(__name__)\napp.config['DATABASE_PATH'] = 'reports.db'\n\ndef get_db_connection():\n    return sqlite3.connect(app.config['DATABASE_PATH'])\n\n@app.route(\"/reports/<team>\")\ndef team_report(team: str) -> Response:\n    \"\"\"Fetch sales report for a specific team.\"\"\"\n    with get_db_connection() as conn:\n        rows = conn.execute(\"SELECT day, total FROM sales WHERE team = ? ORDER BY day\", (team,)).fetchall()\n    return jsonify([list(r) for r in rows])\n\n@app.route(\"/reports/archive\", methods=[\"POST\"])\ndef archive_reports() -> Response:\n    \"\"\"Archive reports directory to a secure location.\"\"\"\n    raw_name = request.form.get(\"name\", \"default\")\n    safe_name = os.path.basename(raw_name)\n    output_path = f\"/tmp/{safe_name}.tgz\"\n    \n    # Using list format to avoid shell injection\n    subprocess.run([\"tar\", \"czf\", output_path, \"reports/\"], check=True)\n    return jsonify(archive=output_path)"
